def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    stressed_bids = []
    weak_opp_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) <= DAILY_SALARY * 1.2 or opp.get('hp', 0) <= 3:
                weak_opp_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 0) <= 3:
                    stressed_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    slots = supply / WATER_REQ
    tight_supply = slots < 2.0
    ample_supply = slots >= 1.8

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    stressed_ref = max(stressed_bids) if stressed_bids else highest_prev

    if hp <= 2 or no_water_days >= 2:
        bid = max(0.92 * DAILY_SALARY, stressed_ref + 2.0, avg_prev + 6.0)
    elif hp <= 4 or no_water_days >= 1:
        if tight_supply:
            bid = max(0.78 * DAILY_SALARY, highest_prev + 1.5)
        else:
            bid = max(0.62 * DAILY_SALARY, avg_prev)
    else:
        if tight_supply:
            bid = max(0.68 * DAILY_SALARY, highest_prev + 1.0)
        elif ample_supply and weak_opp_count >= 1:
            bid = max(18.0, avg_prev * 0.72)
        else:
            bid = max(28.0, avg_prev * 0.88)

    if day >= 8 and hp >= 5 and budget < DAILY_SALARY * 2:
        bid *= 0.9

    if budget < DAILY_SALARY:
        bid = min(bid, budget * 0.92)

    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    remaining_days = EPISODE_DAYS - day_context['day']

    if my_status['hp'] <= 2: 
        return min(my_status['budget'], DAILY_SALARY * 0.95)
    if remaining_days <= 1: 
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    num_slots = int(day_context['supply'] // WATER_REQ)
    num_competitors = len(alive_opponents) + 1 

    if num_slots < num_competitors:
        if my_status['hp'] <= 4: 
            return min(my_status['budget'], max(DAILY_SALARY * 0.75, highest_prev_bid * 1.1 + 2))
        else: 
            return min(my_status['budget'], max(DAILY_SALARY * 0.6, highest_prev_bid * 1.05 + 1))
    else:
        if highest_prev_bid > DAILY_SALARY * 0.7: 
            return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid * 0.9))
        else: 
            return min(my_status['budget'], max(DAILY_SALARY * 0.4, highest_prev_bid + 1))

    return min(my_status['budget'], DAILY_SALARY * 0.5)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from opponent traces to infer pressure.
    prev_bids = []
    prev_bid_by_id = {}
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
            except Exception:
                b = None
        if b is not None:
            prev_bids.append(b)
            prev_bid_by_id[oid] = b

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_highest_prev = 0.0
    if prev_bids:
        sorted_b = sorted(prev_bids)
        if len(sorted_b) >= 2:
            second_highest_prev = sorted_b[-2]

    # Estimate how many water units might be available.
    # If supply is around 15-25 and WATER_REQ=13, typically 1 unit is enough.
    # We aim to be competitive but not wasteful.
    likely_units = int(supply / float(WATER_REQ))
    if likely_units < 1:
        likely_units = 1

    # Baseline bid depends on hp and how risky our no_water streak is.
    if hp <= 2 or no_water_days >= 2:
        baseline = DAILY_SALARY * 0.9
    elif hp <= 4 or no_water_days == 1:
        baseline = DAILY_SALARY * 0.65
    else:
        baseline = DAILY_SALARY * 0.5

    # Exploit: if someone previously overbid very aggressively (Bob-like), we slightly undercut.
    # If highest_prev_bid is extremely high relative to our scale, don't chase fully.
    if highest_prev_bid >= DAILY_SALARY * 0.7:
        # Try to sit just below the top pressure.
        target = min(baseline, highest_prev_bid * 0.92)
        # Ensure at least enough to not be ignored.
        target = max(target, min(baseline, DAILY_SALARY * 0.45))
    else:
        # If pressure was moderate, bid near baseline but nudge above second-highest.
        if second_highest_prev > 0:
            target = max(baseline, second_highest_prev * 1.05)
        else:
            target = baseline

    # Supply-aware cap: when supply is low (closer to 15), competition for the single unit is higher.
    if supply <= float(MIN_SUPPLY) + 0.5:
        target *= 1.08
    elif supply >= float(MAX_SUPPLY) - 0.5:
        target *= 0.95

    # Never exceed budget.
    bid = max(0.0, min(budget, target))

    # If budget is tiny, still bid something minimal to avoid guaranteed no-water.
    if bid <= 0.0 and budget > 0.0:
        bid = min(budget, DAILY_SALARY * 0.1)

    return float(bid)

